import React, { useEffect, useMemo } from 'react';
import ReactMarkdown, { Options } from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Image } from "@arco-design/web-react";
import ImageView from './component/ImageView';
import OutlineView from './component/OutlineView';
import './style.less';





export interface ViewMarkdownProps extends Options {
    text: string;
    isOutline?: boolean;    // 是否展示大纲
}


function ViewMarkdown({ text, isOutline, ...props }: ViewMarkdownProps){

    const components = useMemo(() => {
        return {
            img: (props) => {
                return <ImageView key={props.src} {...props} />;
            },
            h1: ({node, ...props}) => {
                return <h1 id={typeof props.children == 'string'? props.children : undefined} {...props} />
            },
            h2: ({node, ...props}) => {
                return <h2 id={typeof props.children == 'string'? props.children : undefined} {...props} />
            },
        } as Options['components']
    },[])

    
    return (
        <div className="w-full flex items-start">
            <Image.PreviewGroup>
                <ReactMarkdown
                    className='custom-markdown-style'
                    remarkPlugins={[remarkGfm]}
                    {...props}
                    components={components}
                >
                    {text}
                </ReactMarkdown>
            </Image.PreviewGroup>
            {isOutline && (
                <OutlineView 
                    text={text}
                />
            )}
        </div>
    )
}

ViewMarkdown.defaultProps = {
    isOutline: false
}

export default ViewMarkdown;