import React, { useEffect, useMemo, useState } from 'react';
import remarkParse from 'remark-parse';
import { unified } from 'unified';
import classNames from 'classnames';
import _ from 'lodash';

interface OutlineViewProps {
    text: string;
}


const processor = unified().use(remarkParse);
const OutlineView = ({ text }: OutlineViewProps) => {

    const [list, setList] = useState<Array<{ name: string, depth: number }>>([]);
    
    useEffect(() => {
        const tree = processor.parse(text);
        const arr = [];
        for (const item of tree.children) {
            if(item.type == 'heading' && item.depth <= 2){
                if(_.get(item, ['children', 0, 'type']) == 'text'){
                    const textValue = _.get(item, ['children', 0, 'value']);
                    console.log('item', item, textValue)
                    if(textValue){
                        arr.push({ name: textValue, depth: item.depth })
                    }
                }
            }
        }
        setList(arr);
    },[text])

    return (
        <div className="sticky top-2 flex flex-col border-s border-dotted border-neutral-300 w-32">
            {list.map((o, i) => {
                return (
                    <div key={i}
                        className={classNames({
                            "truncate leading-7 text-stone-700 cursor-pointer hover:bg-slate-200 hover:text-blue-500": true,
                            'ml-4': o.depth == 1,
                            'ml-4 pl-4': o.depth == 2,
                        })}
                        onClick={() => {
                            const dom = document.getElementById(o.name);
                            if(dom){
                                dom.scrollIntoView({ behavior: 'smooth' });
                            }
                        }}
                    >
                        {o.name}
                    </div>
                )
            })}
        </div>
    )
}


export default OutlineView;