import classNames from 'classnames';
import utils from 'utils';
import { HTMLProps, useMemo } from 'react';
import { Image } from "@arco-design/web-react";

interface ImageViewProps extends HTMLProps<HTMLImageElement> {

}

const ImageView = (props: ImageViewProps) => {
    const { alt, src } = props;
    const { w, h, align } = useMemo(() => {
        const data = utils.getAllQueryParam(src);
        return {
            ...data,
            w: Number(data.w) || data.w,
            h: Number(data.h) || data.h,
        } as any
    },[])

    if(align == "center" || align == "right"){
        return (
            <div
                className={classNames({
                    ['c-image-center']: align == "center",
                    ['c-image-right']: align == "right",
                })}
            >
                <Image alt={alt}
                    src={src}
                    style={{ width: w, height: h }}
                />
            </div>
        )
    }
    return (
        <Image alt={alt}
            src={src}
            style={{ width: w, height: h }}
        />
    )
}

export default ImageView;